  <section class="card"><h2>软件库设置</h2><p class="admin-muted">控制软件库系统是否启用，以及首页使用论坛首页还是软件库首页。关闭软件库后，前台软件库、投稿、详情、下载等入口将全局不可用。</p><form onsubmit="return saveSoftwareSettings(this)"><div class="admin-form-grid"><label>软件库系统<select name="software_store_enabled"><option value="1" <?= ($softwareSettings['software_store_enabled'] ?? '1') === '1' ? 'selected' : '' ?>>开启</option><option value="0" <?= ($softwareSettings['software_store_enabled'] ?? '1') !== '1' ? 'selected' : '' ?>>关闭</option></select></label><label>首页样式<select name="site_mode"><option value="forum" <?= ($softwareSettings['site_mode'] ?? 'forum') === 'forum' ? 'selected' : '' ?>>论坛首页</option><option value="store" <?= ($softwareSettings['site_mode'] ?? 'forum') === 'store' ? 'selected' : '' ?>>软件库首页</option></select></label></div><div class="admin-muted" style="margin-top:10px">提示：如果关闭软件库系统，保存时会自动把首页样式改回论坛首页，避免首页进入已关闭的软件库。</div><div style="margin-top:12px;display:flex;gap:8px;flex-wrap:wrap"><button class="btn" type="submit">保存软件库设置</button><a class="btn btn-light" href="/index.php?path=software" target="_blank">查看前台软件库</a></div></form></section>
  <?php endif; ?>
  <?php if ($tab === 'stats'): ?><section class="card"><h2>运营统计</h2><div class="software-stat-panel"><div class="card"><div class="software-stat-big"><?= (int)$stats['total'] ?></div><div class="software-stat-label">软件总数</div></div><div class="card"><div class="software-stat-big" style="color:var(--cb-admin-ok)"><?= (int)$stats['published'] ?></div><div class="software-stat-label">已上架</div></div><div class="card"><div class="software-stat-big" style="color:var(--cb-admin-warn)"><?= (int)$stats['pending'] ?></div><div class="software-stat-label">审核中</div></div><div class="card"><div class="software-stat-big"><?= (int)$stats['categories'] ?></div><div class="software-stat-label">分类数量</div></div><div class="card"><div class="software-stat-big"><?= number_format((int)$stats['downloads']) ?></div><div class="software-stat-label">累计下载</div></div><div class="card"><div class="software-stat-big" style="color:var(--cb-admin-danger)"><?= (int)$stats['removed'] ?></div><div class="software-stat-label">已下架 / 删除</div></div></div></section><?php endif; ?>
</div>
<div id="softwareActionModal" style="display:none;position:fixed;inset:0;background:rgba(0,0,0,.5);align-items:center;justify-content:center;z-index:9999"><div style="background:var(--cb-admin-surface);border:1px solid var(--cb-admin-line);border-radius:16px;padding:24px;width:min(420px,90vw);box-shadow:var(--cb-admin-shadow)"><h3 id="modalTitle" style="font-size:16px;font-weight:950;margin:0 0 14px;color:var(--cb-admin-text)">操作</h3><textarea id="modalNote" class="textarea" placeholder="备注（可选）..."></textarea><div style="display:flex;gap:8px;justify-content:flex-end;margin-top:12px"><button class="btn btn-light" type="button" onclick="closeModal()">取消</button><button class="btn" type="button" id="modalConfirm">确认</button></div></div></div>
<script>
var curId=0,curAction='';function openModal(title){document.getElementById('modalTitle').textContent=title;document.getElementById('softwareActionModal').style.display='flex';document.getElementById('modalNote').value='';}function closeModal(){document.getElementById('softwareActionModal').style.display='none';}function doReview(id,action){openModal(action==='approve'?'通过审核':'拒绝审核');curId=id;curAction='review_'+action;document.getElementById('modalNote').required=action==='reject';}function doVersionReview(id,action){openModal(action==='approve'?'通过新版本':'拒绝新版本');curId=id;curAction='version_'+action;document.getElementById('modalNote').required=action==='reject';}function doAction(id,action){openModal(action==='unpublish'?'下架软件':'删除软件');curId=id;curAction=action;document.getElementById('modalNote').required=false;}document.getElementById('modalConfirm').onclick=function(){var n=document.getElementById('modalNote').value;var url='',d='',act=curAction;if(act==='unpublish'){url='/admin.php?path=software/unpublish';d='id='+curId+'&reason='+encodeURIComponent(n);}else if(act==='remove'){url='/admin.php?path=software/remove';d='id='+curId+'&reason='+encodeURIComponent(n);}else if(act==='review_approve'){url='/admin.php?path=software/review';d='id='+curId+'&action=approve&note='+encodeURIComponent(n);}else if(act==='review_reject'){url='/admin.php?path=software/review';d='id='+curId+'&action=reject&note='+encodeURIComponent(n);}else if(act==='version_approve'){url='/admin.php?path=software/version-review';d='id='+curId+'&action=approve&note='+encodeURIComponent(n);}else if(act==='version_reject'){url='/admin.php?path=software/version-review';d='id='+curId+'&action=reject&note='+encodeURIComponent(n);}else return;fetch(url,{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:d,credentials:'same-origin'}).then(r=>r.json()).then(j=>{if(j.ok){closeModal();location.reload();}else alert(j.error||'操作失败');}).catch(e=>alert('请求失败：'+e.message));};
function saveCat(f){var d='id='+encodeURIComponent(f.elements['id'].value)+'&name='+encodeURIComponent(f.elements['name'].value)+'&slug='+encodeURIComponent(f.elements['slug'].value)+'&icon='+encodeURIComponent(f.elements['icon'].value)+'&sort_order='+encodeURIComponent(f.elements['sort_order'].value);fetch('/admin.php?path=software/categories/save',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:d,credentials:'same-origin'}).then(r=>r.json()).then(j=>{if(j.ok){location.href='<?= $baseUrl ?>&tab=categories';}else alert(j.error||'保存失败');}).catch(e=>alert('请求失败：'+e.message));return false;}function editCat(args){document.getElementById('catId').value=args[0];document.getElementById('catName').value=args[1];document.getElementById('catSlug').value=args[2];document.getElementById('catIcon').value=args[3];document.getElementById('catSort').value=args[4];document.getElementById('catName').scrollIntoView({block:'center',behavior:'smooth'});}function resetCatForm(){document.getElementById('catId').value='';document.getElementById('catName').value='';document.getElementById('catSlug').value='';document.getElementById('catIcon').value='';document.getElementById('catSort').value='0';}function delCat(id){if(!confirm('确定删除该分类？'))return;fetch('/admin.php?path=software/categories/delete',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:'id='+encodeURIComponent(id),credentials:'same-origin'}).then(r=>r.json()).then(j=>{if(j.ok){location.href='<?= $baseUrl ?>&tab=categories';}else alert(j.error||'删除失败');}).catch(e=>alert('请求失败：'+e.message));}
function toggleRecommend(id,on){fetch('/admin.php?path=software/recommend',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:'id='+encodeURIComponent(id)+'&recommended='+(on?'1':'0'),credentials:'same-origin'}).then(r=>r.json()).then(j=>{if(j.ok){location.reload();}else alert(j.error||'操作失败');}).catch(e=>alert('请求失败：'+e.message));}
function saveSoftwareSettings(f){var enabled=f.elements['software_store_enabled'].value;var mode=f.elements['site_mode'].value;if(enabled!=='1'&&mode==='store'){mode='forum';}var d='software_store_enabled='+encodeURIComponent(enabled)+'&site_mode='+encodeURIComponent(mode);fetch('/admin.php?path=software/settings/save',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:d,credentials:'same-origin'}).then(r=>r.json()).then(j=>{if(j.ok){location.href='<?= $baseUrl ?>&tab=settings';}else alert(j.error||'保存失败');}).catch(e=>alert('请求失败：'+e.message));return false;}function saveType(f){var d='id='+encodeURIComponent(f.elements['id'].value)+'&name='+encodeURIComponent(f.elements['name'].value)+'&slug='+encodeURIComponent(f.elements['slug'].value)+'&color='+encodeURIComponent(f.elements['color'].value)+'&sort_order='+encodeURIComponent(f.elements['sort_order'].value)+'&status='+encodeURIComponent(f.elements['status'].value)+'&selectable_scope='+encodeURIComponent(f.elements['selectable_scope'].value);fetch('/admin.php?path=software/types/save',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:d,credentials:'same-origin'}).then(r=>r.json()).then(j=>{if(j.ok){location.href='<?= $baseUrl ?>&tab=types';}else alert(j.error||'保存失败');}).catch(e=>alert('请求失败：'+e.message));return false;}function editType(args){document.getElementById('typeId').value=args[0];document.getElementById('typeName').value=args[1];document.getElementById('typeSlug').value=args[2];document.getElementById('typeColor').value=args[3]||'#3cc9a4';document.getElementById('typeSort').value=args[4];document.getElementById('typeStatus').value=args[5]||'active';document.getElementById('typeScope').value=args[6]||'user';document.getElementById('typeName').scrollIntoView({block:'center',behavior:'smooth'});}function resetTypeForm(){document.getElementById('typeId').value='';document.getElementById('typeName').value='';document.getElementById('typeSlug').value='';document.getElementById('typeColor').value='#3cc9a4';document.getElementById('typeSort').value='0';document.getElementById('typeStatus').value='active';document.getElementById('typeScope').value='user';}function delType(id){if(!confirm('确定删除该标识？已使用该标识的软件将显示为原始标识值。'))return;fetch('/admin.php?path=software/types/delete',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:'id='+encodeURIComponent(id),credentials:'same-origin'}).then(r=>r.json()).then(j=>{if(j.ok){location.href='<?= $baseUrl ?>&tab=types';}else alert(j.error||'删除失败');}).catch(e=>alert('请求失败：'+e.message));}
</script>
